#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);   // если дисплей молчит — попробуйте 0x3F

const unsigned long SCROLL_MS = 300;  // меньше = быстрее бег строки

// Слот 1: маленькая "o" с чертой снизу; вместе с буквой N читается как "№"
byte numSign[8] = {
  0b01110,
  0b10001,
  0b10001,
  0b01110,
  0b00000,
  0b00000,
  0b11111,
  0b00000
};

String msg;
uint16_t pos = 0;
unsigned long tPrev = 0;

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.createChar(1, numSign);

  msg  = " Misha Lentyai N";
  msg += (char)1;            // N + глиф = №
  msg += "1 *** ";

  lcd.clear();
}

void loop() {
  unsigned long now = millis();
  if (now - tPrev < SCROLL_MS) return;
  tPrev = now;

  char line[17];
  for (byte i = 0; i < 16; i++)
    line[i] = msg[(pos + i) % msg.length()];
  line[16] = 0;

  lcd.setCursor(0, 0);
  lcd.print(line);

  pos = (pos + 1) % msg.length();
}
